6	// FusedAddRmsnorm op_host — tiling calculation + strategy dispatch + EXEC_KERNEL_CMD launch
7	
8	#include <algorithm>
9	#include <cstdint>
10	
11	#include <torch/extension.h>
12	#include <torch/library.h>
13	
14	#include "torch_kernel_helper.h"
15	#include "tiling/platform/platform_ascendc.h"
16	
17	#include "aclrtlaunch_fused_add_rmsnorm_merge_n.h"
18	#include "aclrtlaunch_fused_add_rmsnorm_single_row.h"
19	#include "aclrtlaunch_fused_add_rmsnorm_splitd.h"
20	
21	// ---------------------------------------------------------------------------
22	// Tiling constants
23	// ---------------------------------------------------------------------------
24	
25	constexpr int32_t DEFAULT_BLOCK_M = 64;
26	constexpr int32_t DEFAULT_ROW_FACTOR = 8;
27	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
28	
29	// ---------------------------------------------------------------------------
30	// Host function
31	// ---------------------------------------------------------------------------
32	
33	namespace ascend_kernel {
34	
35	at::Tensor fused_add_rmsnorm(
36	    const at::Tensor &hidden_states,
37	    const at::Tensor &residual,
38	    const at::Tensor &weight,
39	    double eps)
40	{
41	    TORCH_CHECK(hidden_states.dim() == 2, "hidden_states must be [M, N]");
42	    TORCH_CHECK(residual.dim() == 2, "residual must be [M, N]");
43	    TORCH_CHECK(weight.dim() == 1, "weight must be [N]");
44	    TORCH_CHECK(hidden_states.sizes() == residual.sizes(), "hidden_states and residual must have same shape");
45	    TORCH_CHECK(
46	        hidden_states.scalar_type() == at::kFloat || hidden_states.scalar_type() == at::kHalf ||
47	            hidden_states.scalar_type() == at::kBFloat16,
48	        "hidden_states must be float16, float32, or bfloat16");
49	    TORCH_CHECK(residual.scalar_type() == hidden_states.scalar_type(),
50	        "residual must have the same dtype as hidden_states");
51	    TORCH_CHECK(weight.scalar_type() == hidden_states.scalar_type(),
52	        "weight must have the same dtype as hidden_states");
53	    TORCH_CHECK(hidden_states.is_contiguous(), "hidden_states must be contiguous");
54	    TORCH_CHECK(residual.is_contiguous(), "residual must be contiguous");
55	    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");
56	    TORCH_CHECK(static_cast<int32_t>(hidden_states.sizes()[1]) == static_cast<int32_t>(weight.sizes()[0]),
57	        "weight shape mismatch");
58	
59	    int32_t M = static_cast<int32_t>(hidden_states.sizes()[0]);
60	    int32_t N = static_cast<int32_t>(hidden_states.sizes()[1]);
61	
62	    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
63	    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
64	    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;
65	
66	    at::Tensor y = at::empty_like(hidden_states);
67	
68	    // dtype flag: 0=fp32, 1=fp16, 2=bf16
69	    int64_t dtypeFlag = 0;
70	    if (hidden_states.scalar_type() == at::kHalf) {
71	        dtypeFlag = 1;
72	    } else if (hidden_states.scalar_type() == at::kBFloat16) {
73	        dtypeFlag = 2;
74	    }
75	
76	    // All tiling params as left values (required by EXEC_KERNEL_CMD)
77	    int32_t blockM = DEFAULT_BLOCK_M;
78	    int32_t rowFactor = DEFAULT_ROW_FACTOR;
79	    float epsVal = static_cast<float>(eps);
80	    float invN = 1.0f / static_cast<float>(N);
81	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
82	
83	    // Strategy dispatch
84	    if (N <= 1024) {
85	        EXEC_KERNEL_CMD(fused_add_rmsnorm_merge_n, blockDim,
86	                        hidden_states, residual, weight, y,
87	                        M, N, blockM, usedCoreNum, tasksPerCore, rowFactor, epsVal, invN,
88	                        dtypeFlag);
89	    } else if (N > 8192) {
90	        EXEC_KERNEL_CMD(fused_add_rmsnorm_splitd, blockDim,
91	                        hidden_states, residual, weight, y,
92	                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
93	                        dtypeFlag);
94	    } else {
95	        EXEC_KERNEL_CMD(fused_add_rmsnorm_single_row, blockDim,
96	                        hidden_states, residual, weight, y,
97	                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
98	                        dtypeFlag);
99	    }
100	
101	    return y;
102	}
103	
104	}  // namespace ascend_kernel
105

