5	
6	// AscendC FusedAddRmsnorm kernel — 3 strategies: merge_n, single_row, splitd
7	// Supports float32, float16, bfloat16
8	// Formula: x = hidden_states + residual; y = (x * rsqrt(mean(x^2) + eps)) * weight
9	
10	#include "kernel_operator.h"
11	
12	constexpr int32_t BUFFER_NUM = 1;
13	
14	// ---------------------------------------------------------------------------
15	// Inline helpers
16	// ---------------------------------------------------------------------------
17	
18	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
19	{
20	    if (b == 0U) { return 0U; }
21	    return (a + b - 1U) / b;
22	}
23	
24	template <typename T>
25	__aicore__ inline void LoadGmToUb(
26	    AscendC::LocalTensor<T> &dst,
27	    AscendC::GlobalTensor<T> src,
28	    uint32_t count)
29	{
30	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
31	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
32	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
33	}
34	
35	template <typename T>
36	__aicore__ inline void StoreUbToGm(
37	    AscendC::GlobalTensor<T> dst,
38	    AscendC::LocalTensor<T> &src,
39	    uint32_t count)
40	{
41	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
42	    AscendC::DataCopyPad(dst, src, copyParams);
43	}
44	
45	__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
46	{
47	    if (blockM == 0) { return 0; }
48	    return (M + blockM - 1) / blockM;
49	}
50	
51	template <typename T>
52	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
53	{
54	    if constexpr (std::is_same_v<T, bfloat16_t>) {
55	        return AscendC::RoundMode::CAST_ROUND;
56	    }
57	    return AscendC::RoundMode::CAST_NONE;
58	}
59	
60	template <typename T>
61	__aicore__ inline void PrepareInputTensorHelper(
62	    AscendC::LocalTensor<float> &dst,
63	    AscendC::LocalTensor<T> &src,
64	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
65	    int32_t count)
66	{
67	    if constexpr (std::is_same_v<T, float>) {
68	        dst = src.template ReinterpretCast<float>();
69	    } else {
70	        dst = castBuf.Get<float>();
71	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
72	        AscendC::PipeBarrier<PIPE_V>();
73	    }
74	}
75	
76	template <typename T>
77	__aicore__ inline void PrepareOutputTensorHelper(
78	    AscendC::LocalTensor<float> &dst,
79	    AscendC::LocalTensor<T> &out,
80	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
81	{
82	    if constexpr (std::is_same_v<T, float>) {
83	        dst = out.template ReinterpretCast<float>();
84	    } else {
85	        dst = castBuf.Get<float>();
86	    }
87	}
88	
89	template <typename T>
90	__aicore__ inline void FinalizeOutputTensorHelper(
91	    AscendC::LocalTensor<T> &out,
92	    AscendC::LocalTensor<float> &src,
93	    int32_t count)
94	{
95	    if constexpr (!std::is_same_v<T, float>) {
96	        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
97	        AscendC::PipeBarrier<PIPE_V>();
98	    }
99	}
100	
101	// =========================================================================
102	// Strategy 1: merge_n — preferred when N <= 1024
103	// =========================================================================
104	
105	template <typename dataType>
106	class FusedAddRmsnormMergeNKernel {
107	public:
108	    __aicore__ inline void Init(
109	        GM_ADDR hidden_states, GM_ADDR residual, GM_ADDR weight, GM_ADDR y,
110	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
111	        int32_t tasksPerCore, int32_t rowFactor, float eps, float invN)
112	    {
113	        this->M = M;
114	        this->N = N;
115	        this->blockM = blockM;
116	        this->usedCoreNum = usedCoreNum;
117	        this->tasksPerCore = tasksPerCore;
118	        this->rowFactor = rowFactor;
119	        this->eps = eps;
120	        this->invN = invN;
121	
122	        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hidden_states), static_cast<uint64_t>(M) * N);
123	        resGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(residual), static_cast<uint64_t>(M) * N);
124	        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), N);
125	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
126	
127	        if ASCEND_IS_AIV { InitAivBuffers(); }
128	    }
129	
130	    __aicore__ inline void InitAivBuffers()
131	    {
132	        subBlockRows_ = blockM / AscendC::GetSubBlockNum();
133	        rowLoops_ = subBlockRows_ / rowFactor;
134	        pipe.InitBuffer(weightBuf_, N * sizeof(dataType));
135	        pipe.InitBuffer(hsInQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
136	        pipe.InitBuffer(resInQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
137	        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kMergeRowFactor * N * sizeof(dataType));
138	        pipe.InitBuffer(xBuf_, kMergeRowFactor * N * sizeof(float));
139	        pipe.InitBuffer(scaleBuf_, kMergeRowFactor * N * sizeof(float));
140	        pipe.InitBuffer(weightTileBuf_, kMergeRowFactor * N * sizeof(float));
141	        pipe.InitBuffer(weightBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
142	        pipe.InitBuffer(scaleBroadcastTmpBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
143	        pipe.InitBuffer(reduceBuf_, 2 * kMergeRowFactor * N * sizeof(uint8_t));
144	        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
145	        if constexpr (!std::is_same_v<dataType, float>) {
146	            pipe.InitBuffer(hsCastBuf_, kMergeRowFactor * N * sizeof(float));
147	            pipe.InitBuffer(resCastBuf_, kMergeRowFactor * N * sizeof(float));
148	            pipe.InitBuffer(weightCastBuf_, N * sizeof(float));
149	            pipe.InitBuffer(yCastBuf_, kMergeRowFactor * N * sizeof(float));
150	        }
151	
152	        const uint32_t weightSrcShape[2] = {1U, static_cast<uint32_t>(N)};
153	        const uint32_t weightDstShape[2] = {
154	            static_cast<uint32_t>(kMergeRowFactor),
155	            static_cast<uint32_t>(N),
156	        };
157	
158	        weightInLocal_ = weightBuf_.Get<dataType>();
159	        LoadGmToUb(weightInLocal_, weightGM_, static_cast<uint32_t>(N));
160	        AscendC::PipeBarrier<PIPE_MTE2>();
161	        AscendC::PipeBarrier<PIPE_ALL>();
162	        PrepareInputTensorHelper(weightLocal_, weightInLocal_, weightCastBuf_, N);
163	
164	        weightTileLocal_ = weightTileBuf_.Get<float>();
165	        weightBroadcastTmpLocal_ = weightBroadcastTmpBuf_.Get<uint8_t>();
166	        AscendC::PipeBarrier<PIPE_ALL>();
167	        AscendC::Broadcast<float, 2, 0>(
168	            weightTileLocal_,
169	            weightLocal_,
170	            weightDstShape,
171	            weightSrcShape,
172	            weightBroadcastTmpLocal_);
173	        AscendC::PipeBarrier<PIPE_V>();
174	    }
175	
176	    __aicore__ inline void Process()
177	    {
178	        if ASCEND_IS_AIV {
179	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
180	            const int subBlockIdx = AscendC::GetSubBlockIdx();
181	
182	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
183	                const int bx = coreIdx * tasksPerCore + localIdx;
184	                if (bx >= BlockCountHelper(M, blockM)) {
185	                    continue;
186	                }
187	
188	                for (int r = 0; r < rowLoops_; ++r) {
189	                    const int rowBase = bx * blockM + subBlockIdx * subBlockRows_ + r * rowFactor;
190	                    const int validRows = M - rowBase;
191	                    if (validRows > 0) {
192	                        ProcessRows(rowBase, validRows >= kMergeRowFactor ? kMergeRowFactor : validRows);
193	                    }
194	                }
195	            }
196	        }
197	    }
198	
199	private:
200	    static constexpr int kMergeRowFactor = 8;
201	
202	    __aicore__ inline void CopyInHsRes(int32_t rowBase, int32_t count)
203	    {
204	        hsInLocal_ = hsInQueue_.AllocTensor<dataType>();
205	        resInLocal_ = resInQueue_.AllocTensor<dataType>();
206	        LoadGmToUb(hsInLocal_, hsGM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
207	        LoadGmToUb(resInLocal_, resGM_[static_cast<uint64_t>(rowBase) * N], static_cast<uint32_t>(count));
208	        hsInQueue_.EnQue(hsInLocal_);
209	        resInQueue_.EnQue(resInLocal_);
210	    }
211	
212	    __aicore__ inline void CopyOutY(int32_t rowBase, int32_t count)
213	    {
214	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
215	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowBase) * N], yOutLocal_, static_cast<uint32_t>(count));
216	        yOutQueue_.FreeTensor(yOutLocal_);
217	    }
218	
219	    __aicore__ inline void ComputeSingleRow()
220	    {
221	        const uint32_t scaleSrcShape[2] = {1U, 1U};
222	        const uint32_t scaleDstShape[2] = {1U, static_cast<uint32_t>(N)};
223	        const uint32_t reduceShape[2] = {1U, static_cast<uint32_t>(N)};
224	
225	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
226	        xLocal_ = xBuf_.Get<float>();
227	        scaleLocal_ = scaleBuf_.Get<float>();
228	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
229	        sumLocal_ = sumBuf_.Get<float>();
230	        scaleBroadcastTmpLocal_ = scaleBroadcastTmpBuf_.Get<uint8_t>();
231	
232	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
233	        resInLocal_ = resInQueue_.DeQue<dataType>();
234	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, N);
235	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, N);
236	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
237	
238	        // x = hidden_states + residual
239	        AscendC::Add(xLocal_, hsLocal_, resLocal_, N);
240	        // x^2
241	        AscendC::Mul(yLocal_, xLocal_, xLocal_, N);
242	        // reduce_sum(x^2)
243	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
244	            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
245	        // mean + eps
246	        AscendC::Muls(sumLocal_, sumLocal_, invN, 1);
247	        AscendC::Adds(sumLocal_, sumLocal_, eps, 1);
248	        // rsqrt
249	        AscendC::Rsqrt(sumLocal_, sumLocal_, 1);
250	        AscendC::PipeBarrier<PIPE_V>();
251	        AscendC::Broadcast<float, 2, 1>(
252	            scaleLocal_, sumLocal_, scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);
253	
254	        // y = x * rstd * weight (xLocal_ still holds hs+res)
255	        AscendC::Mul(yLocal_, xLocal_, scaleLocal_, N);
256	        AscendC::Mul(yLocal_, yLocal_, weightLocal_, N);
257	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
258	
259	        hsInQueue_.FreeTensor(hsInLocal_);
260	        resInQueue_.FreeTensor(resInLocal_);
261	        yOutQueue_.EnQue(yOutLocal_);
262	    }
263	
264	    __aicore__ inline void ComputeRows(int32_t tileSize)
265	    {
266	        const uint32_t reduceShape[2] = {
267	            static_cast<uint32_t>(kMergeRowFactor),
268	            static_cast<uint32_t>(N),
269	        };
270	        const uint32_t scaleSrcShape[2] = {
271	            static_cast<uint32_t>(kMergeRowFactor),
272	            1U,
273	        };
274	        const uint32_t scaleDstShape[2] = {
275	            static_cast<uint32_t>(kMergeRowFactor),
276	            static_cast<uint32_t>(N),
277	        };
278	
279	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
280	        xLocal_ = xBuf_.Get<float>();
281	        scaleLocal_ = scaleBuf_.Get<float>();
282	        reduceTmpLocal_ = reduceBuf_.Get<uint8_t>();
283	        sumLocal_ = sumBuf_.Get<float>();
284	        scaleBroadcastTmpLocal_ = scaleBroadcastTmpBuf_.Get<uint8_t>();
285	
286	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
287	        resInLocal_ = resInQueue_.DeQue<dataType>();
288	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, tileSize);
289	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, tileSize);
290	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
291	
292	        // x = hidden_states + residual
293	        AscendC::Add(xLocal_, hsLocal_, resLocal_, tileSize);
294	        // x^2
295	        AscendC::Mul(yLocal_, xLocal_, xLocal_, tileSize);
296	        // reduce_sum(x^2)
297	        AscendC::ReduceSum<float, AscendC::Pattern::Reduce::AR, false>(
298	            sumLocal_, yLocal_, reduceTmpLocal_, reduceShape, true);
299	        // mean + eps
300	        AscendC::Muls(sumLocal_, sumLocal_, invN, kMergeRowFactor);
301	        AscendC::Adds(sumLocal_, sumLocal_, eps, kMergeRowFactor);
302	        // rsqrt
303	        AscendC::Rsqrt(sumLocal_, sumLocal_, kMergeRowFactor);
304	        AscendC::PipeBarrier<PIPE_V>();
305	        AscendC::Broadcast<float, 2, 1>(
306	            scaleLocal_, sumLocal_, scaleDstShape, scaleSrcShape, scaleBroadcastTmpLocal_);
307	
308	        // y = x * rstd * weight (xLocal_ still holds hs+res)
309	        AscendC::Mul(yLocal_, xLocal_, scaleLocal_, tileSize);
310	        AscendC::Mul(yLocal_, yLocal_, weightTileLocal_, tileSize);
311	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, tileSize);
312	
313	        hsInQueue_.FreeTensor(hsInLocal_);
314	        resInQueue_.FreeTensor(resInLocal_);
315	        yOutQueue_.EnQue(yOutLocal_);
316	    }
317	
318	    __aicore__ inline void ProcessSingleRow(int rowIdx)
319	    {
320	        CopyInHsRes(rowIdx, N);
321	        ComputeSingleRow();
322	        CopyOutY(rowIdx, N);
323	    }
324	
325	    __aicore__ inline void ProcessRows(int rowBase, int validRows)
326	    {
327	        if (validRows < kMergeRowFactor) {
328	            for (int r = 0; r < validRows; ++r) {
329	                ProcessSingleRow(rowBase + r);
330	            }
331	            return;
332	        }
333	
334	        const int tileSize = kMergeRowFactor * N;
335	        CopyInHsRes(rowBase, tileSize);
336	        ComputeRows(tileSize);
337	        CopyOutY(rowBase, tileSize);
338	    }
