392	// Strategy 2: single_row — preferred when 1024 < N <= 8192
393	// =========================================================================
394	
395	template <typename dataType>
396	class FusedAddRmsnormSingleRowKernel {
397	public:
398	    __aicore__ inline void Init(
399	        GM_ADDR hidden_states, GM_ADDR residual, GM_ADDR weight, GM_ADDR y,
400	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
401	        int32_t tasksPerCore, float eps, float invN)
402	    {
403	        this->M = M;
404	        this->N = N;
405	        this->blockM = blockM;
406	        this->usedCoreNum = usedCoreNum;
407	        this->tasksPerCore = tasksPerCore;
408	        this->eps = eps;
409	        this->invN = invN;
410	
411	        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hidden_states), static_cast<uint64_t>(M) * N);
412	        resGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(residual), static_cast<uint64_t>(M) * N);
413	        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), N);
414	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), static_cast<uint64_t>(M) * N);
415	
416	        if ASCEND_IS_AIV {
417	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
418	            pipe.InitBuffer(weightBuf_, N * sizeof(dataType));
419	            pipe.InitBuffer(hsInQueue_, BUFFER_NUM, N * sizeof(dataType));
420	            pipe.InitBuffer(resInQueue_, BUFFER_NUM, N * sizeof(dataType));
421	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N * sizeof(dataType));
422	            pipe.InitBuffer(xBuf_, N * sizeof(float));
423	            pipe.InitBuffer(reduceBuf_, N * sizeof(float));
424	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
425	            if constexpr (!std::is_same_v<dataType, float>) {
426	                pipe.InitBuffer(hsCastBuf_, N * sizeof(float));
427	                pipe.InitBuffer(resCastBuf_, N * sizeof(float));
428	                pipe.InitBuffer(weightCastBuf_, N * sizeof(float));
429	                pipe.InitBuffer(yCastBuf_, N * sizeof(float));
430	            }
431	
432	            weightInLocal_ = weightBuf_.Get<dataType>();
433	            LoadGmToUb(weightInLocal_, weightGM_, static_cast<uint32_t>(N));
434	            AscendC::PipeBarrier<PIPE_MTE2>();
435	            AscendC::PipeBarrier<PIPE_ALL>();
436	            PrepareInputTensorHelper<dataType>(weightLocal_, weightInLocal_, weightCastBuf_, N);
437	        }
438	    }
439	
440	    __aicore__ inline void Process()
441	    {
442	        if ASCEND_IS_AIV {
443	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
444	            const int subBlockIdx = AscendC::GetSubBlockIdx();
445	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
446	                const int bx = coreIdx * tasksPerCore + localIdx;
447	                if (bx >= BlockCountHelper(M, blockM)) { continue; }
448	                for (int row = 0; row < subBlockRows_; ++row) {
449	                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
450	                    if (rowIdx < M) { ProcessRow(rowIdx); }
451	                }
452	            }
453	        }
454	    }
455	
456	private:
457	    __aicore__ inline void CopyInHsRes(int32_t rowIdx)
458	    {
459	        hsInLocal_ = hsInQueue_.AllocTensor<dataType>();
460	        resInLocal_ = resInQueue_.AllocTensor<dataType>();
461	        LoadGmToUb(hsInLocal_, hsGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
462	        LoadGmToUb(resInLocal_, resGM_[static_cast<uint64_t>(rowIdx) * N], static_cast<uint32_t>(N));
463	        hsInQueue_.EnQue(hsInLocal_);
464	        resInQueue_.EnQue(resInLocal_);
465	    }
466	
467	    __aicore__ inline void CopyOutY(int32_t rowIdx)
468	    {
469	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
470	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N], yOutLocal_, static_cast<uint32_t>(N));
471	        yOutQueue_.FreeTensor(yOutLocal_);
472	    }
473	
474	    __aicore__ inline void ComputeRow()
475	    {
476	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
477	        xLocal_ = xBuf_.Get<float>();
478	        reduceLocal_ = reduceBuf_.Get<float>();
479	        sumLocal_ = sumBuf_.Get<float>();
480	
481	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
482	        resInLocal_ = resInQueue_.DeQue<dataType>();
483	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, N);
484	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, N);
485	
486	        if constexpr (std::is_same_v<dataType, float>) {
487	            yLocal_ = yOutLocal_.template ReinterpretCast<float>();
488	        } else {
489	            yLocal_ = yCastBuf_.Get<float>();
490	            AscendC::Duplicate(yOutLocal_, static_cast<dataType>(0), N);
491	        }
492	
493	        // x = hidden_states + residual
494	        AscendC::Add(xLocal_, hsLocal_, resLocal_, N);
495	        // yLocal_ = x^2
496	        AscendC::Mul(yLocal_, xLocal_, xLocal_, N);
497	        // reduce_sum(x^2)
498	        AscendC::ReduceSum<float>(reduceLocal_, yLocal_, reduceLocal_, N);
499	        float meanSq = reduceLocal_.GetValue(0) * invN + eps;
500	        AscendC::PipeBarrier<PIPE_ALL>();
501	        // rsqrt
502	        AscendC::Duplicate(sumLocal_, meanSq, 1);
503	        AscendC::Rsqrt(sumLocal_, sumLocal_, 1);
504	        AscendC::PipeBarrier<PIPE_ALL>();
505	        float invRms = sumLocal_.GetValue(0);
506	        AscendC::PipeBarrier<PIPE_ALL>();
507	        // y = x * rstd * weight (xLocal_ still holds hs+res)
508	        AscendC::Muls(yLocal_, xLocal_, invRms, N);
509	        AscendC::Mul(yLocal_, yLocal_, weightLocal_, N);
510	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, N);
511	
512	        hsInQueue_.FreeTensor(hsInLocal_);
513	        resInQueue_.FreeTensor(resInLocal_);
514	        yOutQueue_.EnQue(yOutLocal_);
515	    }
516	
517	    __aicore__ inline void ProcessRow(int rowIdx)
518	    {
519	        CopyInHsRes(rowIdx);
520	        ComputeRow();
521	        CopyOutY(rowIdx);
522	    }
523	
524	private:
525	    int32_t M = 0;
526	    int32_t N = 0;
527	    int32_t blockM = 0;
528	    int32_t usedCoreNum = 0;
529	    int32_t tasksPerCore = 0;
530	    float eps = 0.0f;
531	    float invN = 0.0f;
532	    int subBlockRows_ = 0;
533	
534	    AscendC::TPipe pipe;
535	    AscendC::GlobalTensor<dataType> hsGM_;
536	    AscendC::GlobalTensor<dataType> resGM_;
537	    AscendC::GlobalTensor<dataType> weightGM_;
538	    AscendC::GlobalTensor<dataType> yGM_;
539	
540	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> hsInQueue_;
541	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> resInQueue_;
542	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
543	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightBuf_;
544	    AscendC::TBuf<AscendC::TPosition::VECCALC> xBuf_;
545	    AscendC::TBuf<AscendC::TPosition::VECCALC> hsCastBuf_;
546	    AscendC::TBuf<AscendC::TPosition::VECCALC> resCastBuf_;
547	    AscendC::TBuf<AscendC::TPosition::VECCALC> weightCastBuf_;
548	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
549	    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
550	    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
551	
552	    AscendC::LocalTensor<dataType> hsInLocal_;
553	    AscendC::LocalTensor<dataType> resInLocal_;
554	    AscendC::LocalTensor<dataType> yOutLocal_;
555	    AscendC::LocalTensor<dataType> weightInLocal_;
556	    AscendC::LocalTensor<float> hsLocal_;
557	    AscendC::LocalTensor<float> resLocal_;
558	    AscendC::LocalTensor<float> xLocal_;
559	    AscendC::LocalTensor<float> yLocal_;
560	    AscendC::LocalTensor<float> weightLocal_;
561	    AscendC::LocalTensor<float> reduceLocal_;
562	    AscendC::LocalTensor<float> sumLocal_;
563	};
