569	template <typename dataType>
570	class FusedAddRmsnormSplitDKernel {
571	public:
572	    __aicore__ inline void Init(
573	        GM_ADDR hidden_states, GM_ADDR residual, GM_ADDR weight, GM_ADDR y,
574	        int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
575	        int32_t tasksPerCore, float eps, float invN)
