577	        this->M = M;
578	        this->N = N;
579	        this->blockM = blockM;
580	        this->usedCoreNum = usedCoreNum;
581	        this->tasksPerCore = tasksPerCore;
582	        this->eps = eps;
583	        this->invN = invN;
584	
585	        hsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(hidden_states), static_cast<uint64_t>(M) * N);
586	        resGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(residual), static_cast<uint64_t>(M) * N);
