590	        if ASCEND_IS_AIV {
591	            subBlockRows_ = blockM / AscendC::GetSubBlockNum();
592	            pipe.InitBuffer(hsInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
593	            pipe.InitBuffer(resInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
594	            pipe.InitBuffer(weightInQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
595	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, kBlockN * sizeof(dataType));
596	            pipe.InitBuffer(xBuf_, kTileFloatBytes);
597	            pipe.InitBuffer(reduceBuf_, kBlockN * sizeof(float));
598	            pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
599	            pipe.InitBuffer(tempBuf_, kTileFloatBytes);
600	            if constexpr (!std::is_same_v<dataType, float>) {
601	                pipe.InitBuffer(hsCastBuf_, kTileFloatBytes);
602	                pipe.InitBuffer(resCastBuf_, kTileFloatBytes);
603	                pipe.InitBuffer(weightCastBuf_, kTileFloatBytes);
604	                pipe.InitBuffer(yCastBuf_, kTileFloatBytes);
605	            }
606	        }
607	    }
608	
609	    __aicore__ inline void Process()
610	    {
611	        if ASCEND_IS_AIV {
612	            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
613	            const int subBlockIdx = AscendC::GetSubBlockIdx();
614	            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
615	                const int bx = coreIdx * tasksPerCore + localIdx;
616	                if (bx >= BlockCountHelper(M, blockM)) { continue; }
617	                for (int row = 0; row < subBlockRows_; ++row) {
618	                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
619	                    if (rowIdx < M) { ProcessRow(rowIdx); }
620	                }
621	            }
622	        }
623	    }
