625	private:
626	    static constexpr int kBlockN = 1024;
627	    static constexpr uint32_t kTileFloatBytes = kBlockN * sizeof(float);
628	
629	    __aicore__ inline int32_t NumTiles() const
630	    {
631	        return (N + kBlockN - 1) / kBlockN;
632	    }
633	
634	    __aicore__ inline int32_t GetValidN(int32_t colBase) const
635	    {
636	        return (colBase + kBlockN <= N) ? kBlockN : (N - colBase);
637	    }
638	
639	    __aicore__ inline void CopyInHsRes(int32_t rowIdx, int32_t colBase, int32_t validN)
640	    {
641	        hsInLocal_ = hsInQueue_.AllocTensor<dataType>();
642	        resInLocal_ = resInQueue_.AllocTensor<dataType>();
643	        LoadGmToUb(hsInLocal_, hsGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
644	        LoadGmToUb(resInLocal_, resGM_[static_cast<uint64_t>(rowIdx) * N + colBase], static_cast<uint32_t>(validN));
645	        hsInQueue_.EnQue(hsInLocal_);
646	        resInQueue_.EnQue(resInLocal_);
647	    }
648	
649	    __aicore__ inline void CopyInWeight(int32_t colBase, int32_t validN)
650	    {
651	        weightInLocal_ = weightInQueue_.AllocTensor<dataType>();
652	        LoadGmToUb(weightInLocal_, weightGM_[colBase], static_cast<uint32_t>(validN));
653	        weightInQueue_.EnQue(weightInLocal_);
654	    }
655	
656	    __aicore__ inline void CopyOutY(int32_t rowIdx, int32_t colBase, int32_t validN)
657	    {
658	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
659	        StoreUbToGm(yGM_[static_cast<uint64_t>(rowIdx) * N + colBase], yOutLocal_, static_cast<uint32_t>(validN));
660	        yOutQueue_.FreeTensor(yOutLocal_);
661	    }
662	
663	    __aicore__ inline float ComputeInvRms(int32_t rowIdx)
664	    {
665	        reduceLocal_ = reduceBuf_.Get<float>();
666	        sumLocal_ = sumBuf_.Get<float>();
667	        xLocal_ = xBuf_.Get<float>();
668	        float sumSq = 0.0f;
669	
670	        for (int by = 0; by < NumTiles(); ++by) {
671	            const int colBase = by * kBlockN;
672	            const int validN = GetValidN(colBase);
673	
674	            CopyInHsRes(rowIdx, colBase, validN);
675	
676	            hsInLocal_ = hsInQueue_.DeQue<dataType>();
677	            resInLocal_ = resInQueue_.DeQue<dataType>();
678	            PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, validN);
679	            PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, validN);
680	            // x = hs + res
681	            AscendC::Add(xLocal_, hsLocal_, resLocal_, validN);
682	            // x^2
683	            AscendC::Mul(xLocal_, xLocal_, xLocal_, validN);
684	            AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceLocal_, validN);
685	            sumSq += sumLocal_.GetValue(0);
686	            hsInQueue_.FreeTensor(hsInLocal_);
687	            resInQueue_.FreeTensor(resInLocal_);
688	        }
689	
690	        AscendC::Duplicate(sumLocal_, sumSq * invN + eps, 1);
691	        AscendC::Rsqrt(sumLocal_, sumLocal_, 1);
692	        AscendC::PipeBarrier<PIPE_ALL>();
693	        float invRms = sumLocal_.GetValue(0);
694	        AscendC::PipeBarrier<PIPE_ALL>();
695	        return invRms;
696	    }
697	
698	    __aicore__ inline void ComputeTile(float invRms, int32_t validN)
699	    {
700	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
701	        xLocal_ = xBuf_.Get<float>();
702	        hsInLocal_ = hsInQueue_.DeQue<dataType>();
703	        resInLocal_ = resInQueue_.DeQue<dataType>();
704	        weightInLocal_ = weightInQueue_.DeQue<dataType>();
705	        PrepareInputTensorHelper<dataType>(hsLocal_, hsInLocal_, hsCastBuf_, validN);
706	        PrepareInputTensorHelper<dataType>(resLocal_, resInLocal_, resCastBuf_, validN);
707	        PrepareInputTensorHelper<dataType>(weightLocal_, weightInLocal_, weightCastBuf_, validN);
708	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
709	
710	        // x = hs + res
711	        AscendC::Add(xLocal_, hsLocal_, resLocal_, validN);
712	        // y = x * rstd * weight
713	        AscendC::Muls(yLocal_, xLocal_, invRms, validN);
714	        AscendC::Mul(yLocal_, yLocal_, weightLocal_, validN);
715	        FinalizeOutputTensorHelper<dataType>(yOutLocal_, yLocal_, validN);
716	
717	        hsInQueue_.FreeTensor(hsInLocal_);
718	        resInQueue_.FreeTensor(resInLocal_);
719	        weightInQueue_.FreeTensor(weightInLocal_);
720	        yOutQueue_.EnQue(yOutLocal_);
721	    }
722	
723	    __aicore__ inline void ProcessRow(int rowIdx)
724	    {
725	        float invRms = ComputeInvRms(rowIdx);
726	
727	        for (int by = 0; by < NumTiles(); ++by) {
728	            const int colBase = by * kBlockN;
729	            const int validN = GetValidN(colBase);
730	
731	            CopyInHsRes(rowIdx, colBase, validN);
732	            CopyInWeight(colBase, validN);
733	            ComputeTile(invRms, validN);
734	            CopyOutY(rowIdx, colBase, validN);
735	        }
736	    }
