// AscendC SwiGLU + Group Quantization kernel — single strategy
// Supports float32, float16, bfloat16 input
// SwiGLU: sigmoid(gate) * gate * other
// Quantization: dynamic (per-row absmax) or static

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    const AscendC::GlobalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    const AscendC::GlobalTensor<T> &dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

__aicore__ inline int32_t BlockCountHelper(int32_t M, int32_t blockM)
{
    if (blockM == 0) { return 0; }
    return (M + blockM - 1) / blockM;
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void PrepareInputFloat(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// SwiGLU + Group Quantization Kernel
// =========================================================================

template <typename dataType>
class SwigluQuantKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x_in,
        GM_ADDR smooth_scales,
        GM_ADDR offsets,
        GM_ADDR row_to_group,
        GM_ADDR quantized,
        GM_ADDR quant_scales,
        int32_t M,
        int32_t halfSize,
        int32_t numGroups,
        int32_t blockM,
        int32_t usedCoreNum,
        int32_t tasksPerCore,
        int32_t blockN,
        int64_t activateLeft,
        int64_t quantMode,
        int64_t groupListType,
        float intScale,
        float clipMin,
        float clipMax,
        int64_t isInt4)
    {
        this->M = M;
        this->halfSize = halfSize;
        this->numGroups = numGroups;
        this->blockM = blockM;
        this->usedCoreNum = usedCoreNum;
        this->tasksPerCore = tasksPerCore;
        this->blockN = blockN;
        this->activateLeft = static_cast<int>(activateLeft);
        this->quantMode = static_cast<int>(quantMode);
        this->groupListType = static_cast<int>(groupListType);
        this->intScale = intScale;
        this->clipMin = clipMin;
        this->clipMax = clipMax;
        this->isInt4 = static_cast<int>(isInt4);

        uint64_t M_u64 = static_cast<uint64_t>(M);
        uint64_t halfSize_u64 = static_cast<uint64_t>(halfSize);
        uint64_t halfSize2_u64 = static_cast<uint64_t>(halfSize) * 2;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x_in), M_u64 * halfSize_u64 * 2);
        ssGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(smooth_scales),
                              static_cast<uint64_t>(numGroups) * halfSize_u64);
        offGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(offsets),
                               static_cast<uint64_t>(numGroups) * halfSize_u64);
        rtgGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t *>(row_to_group), M_u64);
        qfyGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(quantized),
                               M_u64 * (isInt4 ? (halfSize_u64 / 2) : halfSize_u64));
        qsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(quant_scales), M_u64);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void InitAivBuffers()
    {
        subBlockRows_ = blockM / AscendC::GetSubBlockNum();

        // Input queues for x (both halves), smooth_scales, offsets
        pipe.InitBuffer(xlInQueue_, BUFFER_NUM, blockN * sizeof(dataType));
        pipe.InitBuffer(xrInQueue_, BUFFER_NUM, blockN * sizeof(dataType));
        pipe.InitBuffer(ssInQueue_, BUFFER_NUM, blockN * sizeof(float));
        pipe.InitBuffer(offInQueue_, BUFFER_NUM, blockN * sizeof(float));
        // Output queue for int8 data
        pipe.InitBuffer(qOutQueue_, BUFFER_NUM, blockN * sizeof(int8_t));

        // Compute floating-point buffers (reused across compute steps)
        pipe.InitBuffer(xlBuf_, blockN * sizeof(float));
        pipe.InitBuffer(xrBuf_, blockN * sizeof(float));
        pipe.InitBuffer(ssBuf_, blockN * sizeof(float));
        pipe.InitBuffer(offBuf_, blockN * sizeof(float));
        pipe.InitBuffer(tmp1Buf_, blockN * sizeof(float));
        pipe.InitBuffer(tmp2Buf_, blockN * sizeof(float));
        pipe.InitBuffer(tmp3Buf_, blockN * sizeof(float));
        pipe.InitBuffer(swigluBuf_, blockN * sizeof(float));
        pipe.InitBuffer(scaledBuf_, blockN * sizeof(float));
        pipe.InitBuffer(maxBuf_, 16 * sizeof(float));
        pipe.InitBuffer(reduceBuf_, 8 * blockN * sizeof(uint8_t));

        // Cast buffers for fp16/bf16 input
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xlCastBuf_, blockN * sizeof(float));
            pipe.InitBuffer(xrCastBuf_, blockN * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tasksPerCore + localIdx;
                if (bx >= BlockCountHelper(M, blockM)) { continue; }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    // =====================================================================
    // Utility: get valid tile size
    // =====================================================================
    __aicore__ inline int32_t GetValidN(int32_t colBase) const
    {
        return (colBase + blockN <= halfSize) ? blockN : (halfSize - colBase);
    }

    // =====================================================================
    // Utility: number of tiles along half_size
    // =====================================================================
    __aicore__ inline int32_t NumTiles() const
    {
        return CeilDivU32(static_cast<uint32_t>(halfSize), static_cast<uint32_t>(blockN));
    }

    // =====================================================================
    // Group lookup: read row_to_group from GM
    // =====================================================================
    __aicore__ inline int32_t GetGroupForRow(int32_t rowIdx) const
    {
        return static_cast<int32_t>(rtgGM_.GetValue(static_cast<uint64_t>(rowIdx)));
    }

    // =====================================================================
    // CopyIn helpers
    // =====================================================================
    __aicore__ inline void CopyInXLeft(int32_t rowIdx, int32_t colBase, int32_t validN)
    {
        xlInLocal_ = xlInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xlInLocal_,
                   xGM_[static_cast<uint64_t>(rowIdx) * halfSize * 2 + colBase],
                   static_cast<uint32_t>(validN));
        xlInQueue_.EnQue(xlInLocal_);
    }

    __aicore__ inline void CopyInXRight(int32_t rowIdx, int32_t colBase, int32_t validN)
    {
        xrInLocal_ = xrInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xrInLocal_,
                   xGM_[static_cast<uint64_t>(rowIdx) * halfSize * 2 + halfSize + colBase],
                   static_cast<uint32_t>(validN));
        xrInQueue_.EnQue(xrInLocal_);
    }

    __aicore__ inline void CopyInSmoothScale(int32_t groupIdx, int32_t colBase, int32_t validN)
    {
        ssInLocal_ = ssInQueue_.AllocTensor<float>();
        LoadGmToUb(ssInLocal_,
                   ssGM_[static_cast<uint64_t>(groupIdx) * halfSize + colBase],
                   static_cast<uint32_t>(validN));
        ssInQueue_.EnQue(ssInLocal_);
    }

    __aicore__ inline void CopyInOffsets(int32_t groupIdx, int32_t colBase, int32_t validN)
    {
        offInLocal_ = offInQueue_.AllocTensor<float>();
        LoadGmToUb(offInLocal_,
                   offGM_[static_cast<uint64_t>(groupIdx) * halfSize + colBase],
                   static_cast<uint32_t>(validN));
        offInQueue_.EnQue(offInLocal_);
    }

    // =====================================================================
    // DeQue helpers
    // =====================================================================
    __aicore__ inline void DeQueAllInputs()
    {
        xlInLocal_ = xlInQueue_.DeQue<dataType>();
        xrInLocal_ = xrInQueue_.DeQue<dataType>();
        ssInLocal_ = ssInQueue_.DeQue<float>();
    }

    __aicore__ inline void DeQueOffsets()
    {
        offInLocal_ = offInQueue_.DeQue<float>();
    }

    __aicore__ inline void FreeAllInputs()
    {
        xlInQueue_.FreeTensor(xlInLocal_);
        xrInQueue_.FreeTensor(xrInLocal_);
        ssInQueue_.FreeTensor(ssInLocal_);
    }

    __aicore__ inline void FreeOffsets()
    {
        offInQueue_.FreeTensor(offInLocal_);
    }

    // =====================================================================
    // Cast inputs to float32
    // =====================================================================
    __aicore__ inline void CastInputsToFloat(int32_t validN)
    {
        xlLocal_ = xlBuf_.Get<float>();
        xrLocal_ = xrBuf_.Get<float>();
        ssLocal_ = ssBuf_.Get<float>();

        PrepareInputFloat<dataType>(xlLocal_, xlInLocal_, xlCastBuf_, validN);
        PrepareInputFloat<dataType>(xrLocal_, xrInLocal_, xrCastBuf_, validN);

        // smooth_scales is always float32
        ssLocal_ = ssInLocal_;

        // offsets are always float32
        offLocal_ = offBuf_.Get<float>();
        offLocal_ = offInLocal_;
    }

    // =====================================================================
    // SwiGLU computation
    // =====================================================================
    __aicore__ inline void ComputeSwiGLU(int32_t validN)
    {
        AscendC::LocalTensor<float> tmp1 = tmp1Buf_.Get<float>();
        AscendC::LocalTensor<float> tmp2 = tmp2Buf_.Get<float>();
        AscendC::LocalTensor<float> tmp3 = tmp3Buf_.Get<float>();
        AscendC::LocalTensor<float> swiglu = swigluBuf_.Get<float>();

        // Determine gate and other halves
        AscendC::LocalTensor<float> gate, other;
        if (activateLeft) {
            gate = xlLocal_;
            other = xrLocal_;
        } else {
            gate = xrLocal_;
            other = xlLocal_;
        }

        // sigmoid(gate) = 1 / (1 + exp(-gate))
        // Step 1: neg_gate = -gate
        AscendC::Muls(tmp1, gate, -1.0f, validN);
        // Step 2: exp_neg_gate = exp(-gate)
        AscendC::Exp(tmp2, tmp1, validN);
        // Step 3: 1 + exp(-gate)
        AscendC::Adds(tmp2, tmp2, 1.0f, validN);
        // Step 4: sigmoid = 1 / (1 + exp(-gate))
        AscendC::Reciprocal(tmp3, tmp2, validN);
        // Step 5: gated = sigmoid * gate
        AscendC::Mul(tmp1, tmp3, gate, validN);
        // Step 6: swiglu = gated * other
        AscendC::Mul(swiglu, tmp1, other, validN);

        // Save swiglu result for later steps
        // (swigluBuf_ already holds the result)
    }

    // =====================================================================
    // Apply smooth scale
    // =====================================================================
    __aicore__ inline void ApplySmoothScale(int32_t validN)
    {
        AscendC::LocalTensor<float> swiglu = swigluBuf_.Get<float>();
        AscendC::LocalTensor<float> scaled = scaledBuf_.Get<float>();
        AscendC::Mul(scaled, swiglu, ssLocal_, validN);
    }

    // =====================================================================
    // Apply offsets (static quantization only)
    // =====================================================================
    __aicore__ inline void ApplyOffsets(int32_t validN)
    {
        AscendC::LocalTensor<float> scaled = scaledBuf_.Get<float>();
        AscendC::Add(scaled, scaled, offLocal_, validN);
    }

    // =====================================================================
    // Track running absmax
    // =====================================================================
    __aicore__ inline void UpdateAbsMax(int32_t validN)
    {
        AscendC::LocalTensor<float> scaled = scaledBuf_.Get<float>();
        AscendC::LocalTensor<float> tmp = tmp2Buf_.Get<float>();
        AscendC::LocalTensor<float> maxVal = maxBuf_.Get<float>();
        AscendC::LocalTensor<uint8_t> reduceTmp = reduceBuf_.Get<uint8_t>();

        // abs(scaled)
        AscendC::Abs(tmp, scaled, validN);
        // ReduceMax over this tile
        AscendC::ReduceMax<float, AscendC::Pattern::Reduce::AR, false>(
            maxVal, tmp, reduceTmp,
            AscendC::ExtensionParam{static_cast<uint32_t>(validN)}, true);
        AscendC::PipeBarrier<PIPE_ALL>();
        // Running max
        float tileMax = maxVal.GetValue(0);
        float prevMax = maxVal.GetValue(0);
        float newMax = (tileMax > prevMax) ? tileMax : prevMax;
        AscendC::Duplicate(maxVal, newMax, 1);
    }

    // =====================================================================
    // Compute dynamic scale: intScale / max(absmax, eps)
    // =====================================================================
    __aicore__ inline float ComputeDynamicScale()
    {
        AscendC::LocalTensor<float> maxVal = maxBuf_.Get<float>();
        float absMax = maxVal.GetValue(0);
        float eps = 1e-10f;
        if (absMax < eps) { absMax = eps; }
        float dynScale = intScale / absMax;
        AscendC::Duplicate(maxVal, dynScale, 1);
        return dynScale;
    }

    // =====================================================================
    // Quantize and clamp
    // =====================================================================
    __aicore__ inline void QuantizeAndClamp(int32_t validN, float dynScale)
    {
        AscendC::LocalTensor<float> scaled = scaledBuf_.Get<float>();
        AscendC::LocalTensor<float> tmp = tmp1Buf_.Get<float>();

        // quant = scaled * dynScale
        AscendC::Muls(tmp, scaled, dynScale, validN);
        // clamp
        AscendC::Maxs(tmp, tmp, clipMin, validN);
        AscendC::Mins(tmp, tmp, clipMax, validN);
        // result stored in scaledBuf_ (reuse for output)
        AscendC::Duplicate(scaled, tmp, validN);
    }

    // =====================================================================
    // Cast float to int8 and pack int4 if needed
    // =====================================================================
    __aicore__ inline void CastAndStore(int32_t rowIdx, int32_t colBase, int32_t validN,
                                         bool isInt4Path)
    {
        AscendC::LocalTensor<float> scaled = scaledBuf_.Get<float>();
        AscendC::LocalTensor<int8_t> qOut = qOutQueue_.AllocTensor<int8_t>();

        // Cast float → int8 (with round)
        AscendC::Cast(qOut, scaled, AscendC::RoundMode::CAST_ROUND, validN);
        AscendC::PipeBarrier<PIPE_V>();

        if (isInt4Path) {
            // int4 packing: pack pairs of int8 values into one byte
            // For i in [0, validN/2): packed[i] = (q[2i] & 0xF) | ((q[2i+1] & 0xF) << 4)
            AscendC::LocalTensor<int8_t> qPacked = tmp3Buf_.Get<int8_t>();
            int halfN = validN / 2;
            for (int i = 0; i < halfN; ++i) {
                int8_t lo = qOut.GetValue(2 * i) & 0x0F;
                int8_t hi = (qOut.GetValue(2 * i + 1) & 0x0F) << 4;
                qPacked.SetValue(i, lo | hi);
            }
            AscendC::PipeBarrier<PIPE_V>();
            qOutQueue_.EnQue(qPacked);
        } else {
            qOutQueue_.EnQue(qOut);
        }
    }

    // =====================================================================
    // CopyOut: store quantized int8 data to GM
    // =====================================================================
    __aicore__ inline void CopyOutQuantized(int32_t rowIdx, int32_t colBase, int32_t validN,
                                              bool isInt4Path)
    {
        AscendC::LocalTensor<int8_t> qDeq;
        if (isInt4Path) {
            // DeQue from tmp3Buf reinterpreted as int8
            qDeq = qOutQueue_.DeQue<int8_t>();
            StoreUbToGm(qfyGM_[static_cast<uint64_t>(rowIdx) * (halfSize / 2) + (colBase / 2)],
                        qDeq, static_cast<uint32_t>(validN / 2));
        } else {
            qDeq = qOutQueue_.DeQue<int8_t>();
            StoreUbToGm(qfyGM_[static_cast<uint64_t>(rowIdx) * halfSize + colBase],
                        qDeq, static_cast<uint32_t>(validN));
        }
        qOutQueue_.FreeTensor(qDeq);
    }

    // =====================================================================
    // Store per-row quant scale
    // =====================================================================
    __aicore__ inline void StoreQuantScale(int32_t rowIdx, float scale)
    {
        AscendC::LocalTensor<float> qs = maxBuf_.Get<float>();
        AscendC::Duplicate(qs, scale, 1);
        AscendC::PipeBarrier<PIPE_ALL>();
        StoreUbToGm(qsGM_[static_cast<uint64_t>(rowIdx)], qs, 1);
    }

    // =====================================================================
    // Process one row: full pipeline
    // =====================================================================
    __aicore__ inline void ProcessRow(int32_t rowIdx)
    {
        int32_t groupIdx = GetGroupForRow(rowIdx);
        int nTiles = NumTiles();

        if (quantMode == 1) {
            // === Dynamic quantization: two-pass ===

            // Pass 1: SwiGLU + Scale + AbsMax tracking
            {
                AscendC::LocalTensor<float> maxVal = maxBuf_.Get<float>();
                AscendC::Duplicate(maxVal, 0.0f, 1);
            }

            for (int tn = 0; tn < nTiles; ++tn) {
                int colBase = tn * blockN;
                int validN = GetValidN(colBase);

                CopyInXLeft(rowIdx, colBase, validN);
                CopyInXRight(rowIdx, colBase, validN);
                CopyInSmoothScale(groupIdx, colBase, validN);
                DeQueAllInputs();
                CastInputsToFloat(validN);
                ComputeSwiGLU(validN);
                ApplySmoothScale(validN);
                UpdateAbsMax(validN);
                FreeAllInputs();
            }

            float dynScale = ComputeDynamicScale();

            // Store per-row scale
            StoreQuantScale(rowIdx, dynScale);

            // Pass 2: recompute SwiGLU + quantize + store
            for (int tn = 0; tn < nTiles; ++tn) {
                int colBase = tn * blockN;
                int validN = GetValidN(colBase);

                CopyInXLeft(rowIdx, colBase, validN);
                CopyInXRight(rowIdx, colBase, validN);
                CopyInSmoothScale(groupIdx, colBase, validN);
                DeQueAllInputs();
                CastInputsToFloat(validN);
                ComputeSwiGLU(validN);
                ApplySmoothScale(validN);
                QuantizeAndClamp(validN, dynScale);
                CastAndStore(rowIdx, colBase, validN, isInt4 != 0);
                CopyOutQuantized(rowIdx, colBase, validN, isInt4 != 0);
                FreeAllInputs();
            }
        } else {
            // === Static quantization: single pass ===

            // Store zero scale
            StoreQuantScale(rowIdx, 0.0f);

            for (int tn = 0; tn < nTiles; ++tn) {
                int colBase = tn * blockN;
                int validN = GetValidN(colBase);

                CopyInXLeft(rowIdx, colBase, validN);
                CopyInXRight(rowIdx, colBase, validN);
                CopyInSmoothScale(groupIdx, colBase, validN);
                CopyInOffsets(groupIdx, colBase, validN);
                DeQueAllInputs();
                DeQueOffsets();
                CastInputsToFloat(validN);
                ComputeSwiGLU(validN);
                ApplySmoothScale(validN);
                ApplyOffsets(validN);
                QuantizeAndClamp(validN, 1.0f /* no per-row scale for static */);
                CastAndStore(rowIdx, colBase, validN, isInt4 != 0);
                CopyOutQuantized(rowIdx, colBase, validN, isInt4 != 0);
                FreeAllInputs();
                FreeOffsets();
            }
        }
    }

private:
    int32_t M = 0;
    int32_t halfSize = 0;
    int32_t numGroups = 0;
    int32_t blockM = 0;
    int32_t usedCoreNum = 0;
    int32_t tasksPerCore = 0;
    int32_t blockN = 0;
    int activateLeft = 0;
