    // TQue (data ingress/egress)
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xlInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xrInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> ssInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> offInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> qOutQueue_;

    // TBuf (compute)
