    AscendC::TBuf<AscendC::TPosition::VECCALC> xlCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xrCastBuf_;

    // Local tensors (queued)
    AscendC::LocalTensor<dataType> xlInLocal_;
    AscendC::LocalTensor<dataType> xrInLocal_;
