// SwiGLU + Group Quantization op_host — tiling + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <vector>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_swiglu_quant.h"

namespace ascend_kernel {

// Tiling constants
constexpr int32_t DEFAULT_BLOCK_M = 64;
constexpr int32_t DEFAULT_BLOCK_N = 256;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

static std::vector<int32_t> buildRowToGroup(
    int32_t prefixDims,
    int32_t numGroups,
    const at::Tensor &groupIndex,
    int64_t groupListType)
{
    std::vector<int32_t> rtg(prefixDims, 0);
    if (numGroups <= 1) { return rtg; }

    auto gi = groupIndex.to(at::kCPU).contiguous();
    const int32_t *giData = gi.data_ptr<int32_t>();

    if (groupListType == 0) {
        // Cumsum mode: boundaries = [0, g0, g1, ...]
        int32_t prev = 0;
        for (int32_t g = 0; g < numGroups; ++g) {
            int32_t boundary = giData[g];
            if (boundary > prefixDims) { boundary = prefixDims; }
            for (int32_t r = prev; r < boundary && r < prefixDims; ++r) {
                rtg[r] = g;
            }
            prev = boundary;
        }
        for (int32_t r = prev; r < prefixDims; ++r) {
            rtg[r] = numGroups - 1;
        }
    } else {
        // Count mode: boundaries = [0, c0, c0+c1, ...]
        int32_t cumsum = 0;
        for (int32_t g = 0; g < numGroups; ++g) {
            int32_t count = giData[g];
            if (count < 0) { count = 0; }
            for (int32_t r = cumsum; r < cumsum + count && r < prefixDims; ++r) {
                rtg[r] = g;
            }
            cumsum += count;
        }
        for (int32_t r = cumsum; r < prefixDims; ++r) {
            rtg[r] = numGroups - 1;
        }
    }
    return rtg;
}

static at::Tensor prepareSmoothScales(
    const at::Tensor &smoothScales,
    int32_t numGroups,
    int32_t halfSize)
{
    auto ss = smoothScales.to(at::kFloat).contiguous();
    if (ss.dim() == 1) {
        // [G] → broadcast to [G, halfSize]
        auto ss2d = at::empty({numGroups, halfSize}, at::kFloat);
        for (int32_t g = 0; g < numGroups; ++g) {
            float val = ss[g].item<float>();
            ss2d[g].fill_(val);
        }
        return ss2d;
    } else if (ss.dim() == 2) {
        int32_t srcN = static_cast<int32_t>(ss.size(1));
        if (srcN == halfSize) { return ss; }
        auto ssPadded = at::zeros({numGroups, halfSize}, at::kFloat);
        int32_t copyN = std::min(srcN, halfSize);
        ssPadded.slice(1, 0, copyN).copy_(ss.slice(1, 0, copyN));
        return ssPadded;
    }
    return at::zeros({numGroups, halfSize}, at::kFloat);
}

static at::Tensor prepareOffsets(
    const at::Tensor &offsets,
    int32_t numGroups,
    int32_t halfSize)
{
    if (!offsets.defined()) {
        return at::zeros({numGroups, halfSize}, at::kFloat);
    }
    auto off = offsets.to(at::kFloat).contiguous();
    if (off.dim() == 1) {
        auto off2d = at::empty({numGroups, halfSize}, at::kFloat);
        for (int32_t g = 0; g < numGroups; ++g) {
            float val = off[g].item<float>();
            off2d[g].fill_(val);
        }
        return off2d;
    } else if (off.dim() == 2) {
        int32_t srcN = static_cast<int32_t>(off.size(1));
        if (srcN == halfSize) { return off; }
        auto offPadded = at::zeros({numGroups, halfSize}, at::kFloat);
        int32_t copyN = std::min(srcN, halfSize);
        offPadded.slice(1, 0, copyN).copy_(off.slice(1, 0, copyN));
        return offPadded;
    }
    return at::zeros({numGroups, halfSize}, at::kFloat);
}

std::tuple<at::Tensor, at::Tensor> swiglu_quant(
    const at::Tensor &x,
    const at::Tensor &smooth_scales,
    const at::Tensor &offsets,
    const at::Tensor &group_index,
    bool activate_left,
    int64_t quant_mode,
    int64_t group_list_type,
    c10::string_view dst_type)
{
    // Input validation
    TORCH_CHECK(x.dim() >= 2, "x must be at least 2D");
    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16,
                "x must be float16, float32, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int32_t lastDim = static_cast<int32_t>(x.size(-1));
    TORCH_CHECK(lastDim % 2 == 0, "last dim of x must be even");

    int32_t halfSize = lastDim / 2;

    // Compute prefix_dims
    auto prefixShape = x.sizes().slice(0, x.dim() - 1);
    int32_t prefixDims = 1;
    for (auto s : prefixShape) { prefixDims *= static_cast<int32_t>(s); }

    // Number of groups
    int32_t numGroups = 1;
    if (group_index.defined() && group_index.numel() > 0) {
        numGroups = static_cast<int32_t>(group_index.size(0));
    }
    if (!smooth_scales.defined() || smooth_scales.numel() == 0) {
        numGroups = 1;
    }

    // Prepare smooth_scales and offsets as [numGroups, halfSize]
    at::Tensor ssPrep, offPrep;
    if (smooth_scales.defined() && smooth_scales.numel() > 0) {
        ssPrep = prepareSmoothScales(smooth_scales, numGroups, halfSize);
    } else {
        ssPrep = at::ones({numGroups, halfSize}, at::kFloat);
    }
    if (quant_mode == 1) {
        offPrep = at::zeros({numGroups, halfSize}, at::kFloat);
    } else {
        offPrep = prepareOffsets(offsets, numGroups, halfSize);
    }

    // Build row-to-group mapping
    at::Tensor rtgTensor;
    if (numGroups <= 1) {
        rtgTensor = at::zeros({prefixDims}, at::kInt);
    } else if (group_index.defined() && group_index.numel() > 0) {
        auto rtgVec = buildRowToGroup(prefixDims, numGroups, group_index, group_list_type);
        rtgTensor = at::from_blob(
            const_cast<int32_t *>(rtgVec.data()),
            {prefixDims},
            at::TensorOptions().dtype(at::kInt).device(at::kPrivateUse1)).clone();
    } else {
        rtgTensor = at::zeros({prefixDims}, at::kInt);
    }

    // Determine int4 or int8
    bool isInt4 = (dst_type == "int4");
    int64_t isInt4Flag = isInt4 ? 1 : 0;

    float intScale, clipMin, clipMax;
    if (isInt4) {
        intScale = 7.0f;
        clipMin = -8.0f;
        clipMax = 7.0f;
    } else {
        intScale = 127.0f;
        clipMin = -128.0f;
        clipMax = 127.0f;
    }

    // Allocate output tensors
    int32_t outLastDim = isInt4 ? (halfSize / 2) : halfSize;
    TORCH_CHECK(outLastDim > 0, "Invalid output last dimension for int4");
    std::vector<int64_t> outShape(prefixShape.begin(), prefixShape.end());
    outShape.push_back(outLastDim);
    at::Tensor quantized = at::empty(outShape, at::kByte);
    std::vector<int64_t> scaleShape(prefixShape.begin(), prefixShape.end());
    at::Tensor quantScales = at::zeros(scaleShape, at::kFloat);

    // Reshape to 2D for kernel launch
    at::Tensor x2d = x.reshape({prefixDims, lastDim}).contiguous();

    // Dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (x.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // Tiling computation
    int32_t mNum = (prefixDims + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    // All parameters as left-values for EXEC_KERNEL_CMD
    int32_t prefixDimsL = prefixDims;
    int32_t halfSizeL = halfSize;
    int32_t numGroupsL = numGroups;
    int32_t blockML = DEFAULT_BLOCK_M;
    int32_t blockNL = DEFAULT_BLOCK_N;
    int64_t activateLeftL = activate_left ? 1 : 0;
    int64_t quantModeL = quant_mode;
    int64_t groupListTypeL = group_list_type;
    float intScaleL = intScale;
    float clipMinL = clipMin;
    float clipMaxL = clipMax;
    int64_t isInt4L = isInt4Flag;
    int64_t dtypeFlagL = dtypeFlag;
    int32_t usedCoreNumL = usedCoreNum;
    int32_t tasksPerCoreL = tasksPerCore;
    uint32_t blockDimL = static_cast<uint32_t>(usedCoreNum);

    EXEC_KERNEL_CMD(swiglu_quant, blockDimL,
                    x2d, ssPrep, offPrep, rtgTensor,
                    quantized, quantScales,
                    prefixDimsL, halfSizeL, numGroupsL,
                    blockML, usedCoreNumL, tasksPerCoreL, blockNL,
                    activateLeftL, quantModeL, groupListTypeL,
                    intScaleL, clipMinL, clipMaxL, isInt4L,
                    dtypeFlagL);

    // Reshape output from 2D back to original prefix shape
    at::Tensor qOut = quantized.reshape(outShape);
    at::Tensor qsOut = quantScales.reshape(scaleShape);
    return std::make_tuple(qOut, qsOut);
}

}  // namespace ascend_kernel
